+    },
+  ];
+}
+
+function loadProductionInputs(root, paths, diagnostics, options = {}) {
+  if (options.inputs) return options.inputs;
+  return {
+    preciseCrops: readJsonInput(root, paths.wave1PreciseCropsIn, 'figureasset_wave1_precise_source_crops', diagnostics),
+    cropQa: readJsonInput(root, paths.wave1CropQaIn, 'figureasset_wave1_crop_completeness_qa', diagnostics),
+    sourceVisualReceiptSchema: readJsonInput(root, paths.sourceVisualReceiptSchemaIn, 'source_visual_receipt_schema', diagnostics),
+  };
+}
+
+function normalizeProductionInputs(inputs, diagnostics) {
+  return {
+    cropArtifacts: sanitizeRows(inputs.preciseCrops, {
+      role: 'figureasset_wave1_precise_source_crops',
+      field: 'crop_artifacts',
+      identityField: 'crop_artifact_id',
+    }, diagnostics),
+    manualReviewRows: sanitizeRows(inputs.preciseCrops, {
+      role: 'figureasset_wave1_precise_source_crops',
+      field: 'manual_review_rows',
+      identityField: 'question_key',
+    }, diagnostics),
+    qaRows: sanitizeRows(inputs.cropQa, {
+      role: 'figureasset_wave1_crop_completeness_qa',
+      field: 'rows',
+      identityField: 'question_key',
+    }, diagnostics),
+    sourceVisualReceiptSchema: validateObjectInput(inputs.sourceVisualReceiptSchema, {
+      role: 'source_visual_receipt_schema',
+    }, diagnostics),
+  };
+}
+
+function productionReceiptId(cropArtifact, qaRow, replay) {
+  return `svr_wave1_${sha256({
+    crop_artifact_id: cropArtifact.crop_artifact_id,
+    question_key: qaRow.question_key,
+    source_page_render_id: cropArtifact.source_page_render?.source_page_render_id ?? null,
+    source_page_render_sha256: cropArtifact.source_page_render?.output_sha256 ?? null,
+    crop_sha256: cropArtifact.crop?.output_sha256 ?? null,
+    replayed_crop_sha256: replay.replayedCropSha256 ?? null,
+    bbox: cropArtifact.bbox?.clamped_pixels ?? null,
+  }).slice(0, 16)}`;
+}
+
+function sourceRenderDimensions(sourceRender) {
+  return {
+    width: firstFiniteNumber(
+      sourceRender?.dimensions_pixels?.width,
+      sourceRender?.page_dimensions?.width_pixels,
+    ),
+    height: firstFiniteNumber(
+      sourceRender?.dimensions_pixels?.height,
+      sourceRender?.page_dimensions?.height_pixels,
+    ),
+  };
+}
+
+function sourcePageRenderRef(sourceRender) {
+  const dimensions = sourceRenderDimensions(sourceRender);
+  return {
+    source_page_render_id: firstString(sourceRender?.source_page_render_id),
+    render_dpi: firstFiniteNumber(sourceRender?.dpi),
+    image_path: firstString(sourceRender?.output_path),
+    width_px: dimensions.width,
+    height_px: dimensions.height,
+    sha256: firstString(sourceRender?.actual_output_sha256, sourceRender?.output_sha256),
+  };
+}
+
+function cropFileRef(cropArtifact) {
+  return {
+    crop_artifact_id: firstString(cropArtifact?.crop_artifact_id),
+    image_path: firstString(cropArtifact?.crop?.output_path),
+    width_px: firstFiniteNumber(cropArtifact?.crop?.dimensions_pixels?.width),
+    height_px: firstFiniteNumber(cropArtifact?.crop?.dimensions_pixels?.height),
+    sha256: firstString(cropArtifact?.crop?.output_sha256),
+    image_format: firstString(cropArtifact?.crop?.image_format),
+  };
+}
+
+function bboxPixels(cropArtifact) {
+  const bbox = cropArtifact?.bbox?.clamped_pixels ?? {};
+  const width = firstFiniteNumber(bbox.width);
+  const height = firstFiniteNumber(bbox.height);
+  const x = firstFiniteNumber(bbox.x, bbox.x_min);
+  const y = firstFiniteNumber(bbox.y, bbox.y_min);
+  if (x === null || y === null || width === null || height === null || width <= 0 || height <= 0) return null;
+  return { x, y, width, height };
+}
+
+async function renderSourcePageForProductionReplay({
+  root,
+  cropArtifact,
+  renderPage,
+  renderer,
+  tempRoot,
+}) {
+  const sourceRender = cropArtifact.source_page_render ?? {};
+  const expectedSha256 = firstString(sourceRender.actual_output_sha256, sourceRender.output_sha256);
+  const existingRenderPath = firstString(sourceRender.output_path);
+  if (existingRenderPath && fs.existsSync(resolvePath(root, existingRenderPath))) {
+    const actualSha256 = sha256File(root, existingRenderPath);
+    return {
+      ok: expectedSha256 ? actualSha256 === expectedSha256 : true,
+      sourceImagePath: resolvePath(root, existingRenderPath),
+      sourceImagePathRole: 'existing_source_page_render_file',
+      expectedSourcePageRenderSha256: expectedSha256,
+      actualSourcePageRenderSha256: actualSha256,
+      blockerCode: expectedSha256 && actualSha256 !== expectedSha256 ? 'source_page_render_sha256_mismatch' : null,
+    };
+  }
+
+  const sourcePdfPath = firstString(sourceRender.source_pdf_path);
+  const pageNumber1Based = firstFiniteNumber(sourceRender.page_number_1based);
+  const dpi = firstFiniteNumber(sourceRender.dpi);
+  if (!sourcePdfPath || pageNumber1Based === null || dpi === null) {
+    return {
+      ok: false,
+      sourceImagePath: null,
+      sourceImagePathRole: 'missing_source_page_render_replay_inputs',
+      expectedSourcePageRenderSha256: expectedSha256,
+      actualSourcePageRenderSha256: null,
+      blockerCode: 'source_page_render_replay_inputs_missing',
+    };
+  }
+
+  const outputPath = path.join(
+    tempRoot,
+    `${firstString(sourceRender.source_page_render_id, cropArtifact.crop_artifact_id, 'source_page')}.png`,
+  );
+  try {
+    await renderPage({
+      root,
+      sourcePdfPath,
+      pageNumber1Based,
+      dpi,
+      outputPath,
+      renderer,
+    });
+  } catch (error) {
+    return {
+      ok: false,
+      sourceImagePath: outputPath,
+      sourceImagePathRole: 'rerendered_source_page_temp_file',
+      expectedSourcePageRenderSha256: expectedSha256,
+      actualSourcePageRenderSha256: null,
+      blockerCode: 'source_page_render_replay_failed',
+      blockerDetail: error instanceof Error ? error.message : String(error),
+    };
+  }
+
+  const actualSha256 = sha256Bytes(fs.readFileSync(outputPath));
+  return {
+    ok: expectedSha256 ? actualSha256 === expectedSha256 : true,
+    sourceImagePath: outputPath,
+    sourceImagePathRole: 'rerendered_source_page_temp_file',
+    expectedSourcePageRenderSha256: expectedSha256,
+    actualSourcePageRenderSha256: actualSha256,
+    blockerCode: expectedSha256 && actualSha256 !== expectedSha256 ? 'source_page_render_sha256_mismatch' : null,
+  };
+}
+
+async function replayCropFromSourcePage(sourceImagePath, bbox) {
+  const sourceImage = await loadImage(sourceImagePath);
+  const canvas = createCanvas(bbox.width, bbox.height);
+  const context = canvas.getContext('2d');
+  context.drawImage(
+    sourceImage,
+    bbox.x,
+    bbox.y,
+    bbox.width,
+    bbox.height,
+    0,
+    0,
+    bbox.width,
+    bbox.height,
+  );
+  const buffer = await canvas.encode('png');
+  return {
+    replayedCropSha256: sha256Bytes(buffer),
+    replayedCropDimensions: {
+      width: canvas.width,
+      height: canvas.height,
+    },
+  };
+}
+
+async function validateProductionCropReplay({
+  root,
+  cropArtifact,
+  renderPage,
+  renderer,
+  tempRoot,
+}) {
+  const cropPath = firstString(cropArtifact.crop?.output_path);
+  const expectedCropSha256 = firstString(cropArtifact.crop?.output_sha256);
+  const actualCropSha256 = cropPath ? sha256File(root, cropPath) : null;
+  const bbox = bboxPixels(cropArtifact);
+  const sourcePageReplay = await renderSourcePageForProductionReplay({
+    root,
+    cropArtifact,
+    renderPage,
+    renderer,
+    tempRoot,
+  });
+  const blockers = [];
+  if (!cropPath || !fs.existsSync(resolvePath(root, cropPath))) blockers.push('crop_file_missing');
+  if (expectedCropSha256 && actualCropSha256 !== expectedCropSha256) blockers.push('crop_manifest_sha256_mismatch');
+  if (!bbox) blockers.push('crop_bbox_missing_or_invalid');
+  if (!sourcePageReplay.ok && sourcePageReplay.blockerCode) blockers.push(sourcePageReplay.blockerCode);
+
+  let replayedCropSha256 = null;
+  let replayedCropDimensions = null;
+  if (blockers.length === 0 && sourcePageReplay.sourceImagePath && bbox) {
+    try {
+      const replayed = await replayCropFromSourcePage(sourcePageReplay.sourceImagePath, bbox);
+      replayedCropSha256 = replayed.replayedCropSha256;
+      replayedCropDimensions = replayed.replayedCropDimensions;
+      if (expectedCropSha256 !== replayedCropSha256) blockers.push('crop_replay_sha256_mismatch');
+    } catch (error) {
+      blockers.push('crop_replay_failed');
+      sourcePageReplay.blockerDetail = error instanceof Error ? error.message : String(error);
+    }
+  }
+
+  return {
+    replayStatus: blockers.length === 0 ? 'replay_validated' : 'blocked_replay_mismatch',
+    cropHashMatch: blockers.length === 0,
+    blockers,
+    bbox,
+    expectedCropSha256,
+    actualCropSha256,
+    replayedCropSha256,
+    replayedCropDimensions,
+    sourcePageReplay,
+  };
+}
+
+function qaBlockerCodes(qaRow) {
+  const codes = asArray(qaRow?.blocker_reasons)
+    .map((item) => firstString(item?.code))
+    .filter(Boolean);
+  return [...new Set(codes)];
+}
+
+function noReceiptBlocker({
+  qaRow,
+  cropArtifact = null,
+  status,
+  blockerCodes,
+  replay = null,
+  paths,
+  qaIndex,
+}) {
+  return {
+    schema_version: 'source_visual_receipt_no_receipt_blocker.v1',
+    question_key: firstString(qaRow?.question_key, cropArtifact?.question_key),
+    question_ref: firstString(qaRow?.question_ref),
+    precise_crop_source_map_row_id: firstString(qaRow?.precise_crop_source_map_row_id, cropArtifact?.precise_crop_source_map_row_id),
+    crop_artifact_ids: cropArtifact
+      ? [cropArtifact.crop_artifact_id].filter(Boolean)
+      : asArray(qaRow?.crop_artifact_ids).filter(Boolean),
+    accepted_crop_artifact_ids: asArray(qaRow?.accepted_crop_artifact_ids).filter(Boolean),
+    visual_qa_posture: firstString(qaRow?.visual_qa_posture),
+    receipt_blocker_status: status,
+    blocker_codes: [...new Set(blockerCodes.filter(Boolean))],
+    blocker_reasons: asArray(qaRow?.blocker_reasons),
+    deterministic_replay_evidence: replay ? {
+      replay_status: replay.replayStatus,
+      expected_crop_sha256: replay.expectedCropSha256,
+      actual_crop_sha256: replay.actualCropSha256,
+      replayed_crop_sha256: replay.replayedCropSha256,
+      source_page_render_sha256: {
+        expected: replay.sourcePageReplay.expectedSourcePageRenderSha256,
+        actual: replay.sourcePageReplay.actualSourcePageRenderSha256,
+      },
+      source_page_render_path_role: replay.sourcePageReplay.sourceImagePathRole,
+    } : null,
+    source_ref: {
+      path: paths.wave1CropQaIn,
+      json_pointer: `/rows/${qaIndex}`,
+    },
+    source_visual_receipt_approved: false,
+    student_display_eligible_final: false,
+    source_figure_accepted_for_student_display: false,
+    rights_display_allowed: false,
+  };
+}
+
+function buildProductionReceipt({
+  cropArtifact,
+  qaRow,
+  replay,
+  generatedAt,
+  paths,
+  qaIndex,
+  cropIndex,
+  materializationConfig,
+}) {
+  const sourceRender = cropArtifact.source_page_render ?? {};
+  const cropRef = cropFileRef(cropArtifact);
+  return {
+    schema_version: 'source_visual_receipt.v1',
+    source_visual_receipt_id: productionReceiptId(cropArtifact, qaRow, replay),
+    question_key: firstString(qaRow.question_key, cropArtifact.question_key),
+    question_ref: firstString(qaRow.question_ref),
+    question_anchor_id: firstString(qaRow.question_ref, qaRow.question_key, cropArtifact.question_key),
+    source_document_id: firstString(sourceRender.source_document_id),
+    source_pdf_path: firstString(sourceRender.source_pdf_path),
+    source_pdf_sha256: firstString(sourceRender.source_pdf_sha256),
+    page_number_1based: firstFiniteNumber(sourceRender.page_number_1based),
+    source_page_render_ref: sourcePageRenderRef(sourceRender),
+    question_render_model_ref: null,
+    figure_asset_refs: [
+      firstString(cropArtifact.source_figure_asset_candidate_metadata?.figure_asset_candidate_id),
+    ].filter(Boolean),
+    crop_ref: cropRef,
+    crop_bbox: cropArtifact.bbox ?? null,
+    historical_crop_refs: [],
+    inspection_sheet_path: null,
+    renderer_settings: {
+      renderer: materializationConfig?.renderer ?? null,
+      coordinate_space: materializationConfig?.coordinate_space ?? cropArtifact.bbox?.coordinate_space ?? null,
+      crop_image_format: materializationConfig?.crop_image_format ?? cropRef.image_format ?? null,
+      source_page_render_dpi: firstFiniteNumber(sourceRender.dpi),
+    },
+    qa_posture: {
+      visual_qa_posture: firstString(qaRow.visual_qa_posture),
+      visual_qa_accepted: qaRow.visual_qa_accepted === true,
+      accepted_crop_artifact_ids: asArray(qaRow.accepted_crop_artifact_ids),
+      deterministic_check_count: asArray(qaRow.qa_evidence?.deterministic_checks).length,
+      blocker_count: asArray(qaRow.blocker_reasons).length,
+      source_ref: {
+        path: paths.wave1CropQaIn,
+        json_pointer: `/rows/${qaIndex}`,
+      },
+    },
+    review_status: 'accepted_replayable_lineage',
+    reviewed_by: 'figureasset_wave1_crop_completeness_qa',
+    reviewed_at: generatedAt,
+    blockers: [],
+    deterministic_replay_authority: {
+      replay_status: replay.replayStatus,
+      crop_hash_match: replay.cropHashMatch,
+      expected_crop_sha256: replay.expectedCropSha256,
+      actual_crop_sha256: replay.actualCropSha256,
+      replayed_crop_sha256: replay.replayedCropSha256,
+      replayed_crop_dimensions: replay.replayedCropDimensions,
+      source_page_render_sha256: {
+        expected: replay.sourcePageReplay.expectedSourcePageRenderSha256,
+        actual: replay.sourcePageReplay.actualSourcePageRenderSha256,
+      },
+      source_page_render_path_role: replay.sourcePageReplay.sourceImagePathRole,
+      bbox_pixels: replay.bbox,
+    },
+    proposal_provenance: {
+      vlm_candidate: cropArtifact.candidate_provenance ?? null,
+      authority: 'proposal_metadata_only_not_receipt_authority',
+    },
+    lineage: {
+      created_from: [
+        paths.wave1PreciseCropsIn,
+        paths.wave1CropQaIn,
+        paths.sourceVisualReceiptSchemaIn,
+      ],
+      source_refs: {
+        precise_crop_artifact: {
+          path: paths.wave1PreciseCropsIn,
+          json_pointer: `/crop_artifacts/${cropIndex}`,
+        },
+        crop_qa_row: {
+          path: paths.wave1CropQaIn,
+          json_pointer: `/rows/${qaIndex}`,
+        },
+      },
+      created_by: 'scripts/method-map/build-source-visual-receipt-replay-harness.mjs',
+      created_at: generatedAt,
+    },
+    source_visual_receipt_approved: true,
+    student_display_eligible_final: false,
+    source_figure_accepted_for_student_display: false,
+    rights_display_allowed: false,
+    rights_display_policy_status: 'not_approved_out_of_scope_for_issue_1252',
+  };
+}
+
+function countProductionPostures(qaRows) {
+  const counts = {};
+  for (const row of qaRows) {
+    const posture = firstString(row.visual_qa_posture) ?? 'unknown';
+    counts[posture] = (counts[posture] ?? 0) + 1;
+  }
+  return Object.fromEntries(Object.entries(counts).sort(([left], [right]) => compareNatural(left, right)));
+}
+
+function buildProductionSummary({ qaRows, cropArtifacts, receipts, noReceiptBlockers, diagnostics }) {
+  const postureCounts = countProductionPostures(qaRows);
+  const receiptCountsByPosture = {};
+  for (const receipt of receipts) {
+    const posture = receipt.qa_posture?.visual_qa_posture ?? 'unknown';
+    receiptCountsByPosture[posture] = (receiptCountsByPosture[posture] ?? 0) + 1;
+  }
+  return {
+    wave1_row_count: qaRows.length,
+    produced_crop_artifact_count: cropArtifacts.length,
+    accepted_receipt_count: receipts.length,
+    replay_validated_receipt_count: receipts.filter((row) => row.deterministic_replay_authority?.crop_hash_match === true).length,
+    no_receipt_blocker_count: noReceiptBlockers.length,
+    replay_mismatch_blocker_count: noReceiptBlockers.filter((row) => asArray(row.blocker_codes).includes('crop_replay_sha256_mismatch')).length,
+    qa_posture_counts: postureCounts,
+    receipt_counts_by_qa_posture: Object.fromEntries(Object.entries(receiptCountsByPosture).sort(([left], [right]) => compareNatural(left, right))),
+    input_diagnostic_count: diagnostics.length,
+    input_error_diagnostic_count: diagnostics.filter((diagnostic) => diagnostic.severity === 'error').length,
+    external_vlm_call_count: 0,
+    source_visual_receipt_approved_true_count: receipts.filter((row) => row.source_visual_receipt_approved === true).length,
+    rights_display_allowed_true_count: receipts.filter((row) => row.rights_display_allowed === true).length,
+    source_figure_accepted_for_student_display_true_count: receipts.filter((row) => row.source_figure_accepted_for_student_display === true).length,
+    student_display_eligible_final_true_count: receipts.filter((row) => row.student_display_eligible_final === true).length,
+  };
+}
+
+function buildProductionReadback(manifest, validatorResult) {
+  const postureLines = Object.entries(manifest.summary.qa_posture_counts)
+    .map(([posture, count]) => `- ${posture}: ${count}`);
+  return [
+    '# Wave 1 SourceVisualReceipt Production Readback',
+    '',
+    `Generated: ${manifest.generated_at}`,
+    '',
+    '## Scope',
+    '',
+    '- Issue: #1252, `[FA-CROP-HVY-08] Generate Wave 1 SourceVisualReceipt production rows`',
+    '- Parent issue: #1243',
+    '- Depends on: #1250 / FA-CROP-HVY-06 and #1251 / FA-CROP-HVY-07',
+    '- External VLM calls performed: 0',
+    '- Receipts prove replayable source lineage only; they do not grant rights/display approval.',
+    '',
+    '## Outputs',
+    '',
+    `- Receipt artifact: \`${manifest.output_paths.production_manifest}\``,
+    `- Readback: \`${manifest.output_paths.readback}\``,
+    `- Validator result: \`${manifest.output_paths.validator}\``,
+    '',
+    '## Counts',
+    '',
+    `- Wave 1 rows: ${manifest.summary.wave1_row_count}`,
+    `- Produced crop artifacts considered: ${manifest.summary.produced_crop_artifact_count}`,
+    `- Accepted SourceVisualReceipt rows: ${manifest.summary.accepted_receipt_count}`,
+    `- Replay-validated receipts: ${manifest.summary.replay_validated_receipt_count}`,
+    `- No-receipt blockers: ${manifest.summary.no_receipt_blocker_count}`,
+    `- Replay mismatch blockers: ${manifest.summary.replay_mismatch_blocker_count}`,
+    '',
+    '## Receipt Counts By Posture',
+    '',
+    ...postureLines,
+    '',
+    '## Boundary',
+    '',
+    `- SourceVisualReceipt approvals: ${manifest.summary.source_visual_receipt_approved_true_count}`,
+    `- Rights-display allowed rows: ${manifest.summary.rights_display_allowed_true_count}`,
+    `- SourceFigureAsset student-display acceptance rows: ${manifest.summary.source_figure_accepted_for_student_display_true_count}`,
+    `- Student-display final rows: ${manifest.summary.student_display_eligible_final_true_count}`,
+    '',
+    '## Validation',
+    '',
+    `- Status: ${validatorResult.summary.validation_status}`,
+    `- Checks: ${validatorResult.summary.check_count}`,
+    `- Failed checks: ${validatorResult.summary.failed_check_count}`,
+  ].join('\n');
+}
+
+function buildProductionValidator({ manifest, readback, diagnostics }) {
+  const receipts = asArray(manifest.receipts);
+  const blockers = asArray(manifest.no_receipt_blockers);
+  const qaRows = asArray(manifest.wave1_row_refs);
+  const acceptedCoverageMissing = [];
+  for (const row of qaRows) {
+    const acceptedIds = asArray(row.accepted_crop_artifact_ids);
+    if (row.visual_qa_accepted === true && acceptedIds.length > 0) {
+      for (const cropArtifactId of acceptedIds) {
+        const hasReceipt = receipts.some((receipt) => receipt.crop_ref?.crop_artifact_id === cropArtifactId);
+        const hasBlocker = blockers.some((blockerRow) => asArray(blockerRow.crop_artifact_ids).includes(cropArtifactId));
+        if (!hasReceipt && !hasBlocker) acceptedCoverageMissing.push({ question_key: row.question_key, crop_artifact_id: cropArtifactId });
+      }
+    } else {
+      const hasBlocker = blockers.some((blockerRow) => blockerRow.question_key === row.question_key);
+      if (!hasBlocker) acceptedCoverageMissing.push({ question_key: row.question_key, crop_artifact_id: null });
+    }
+  }
+
+  const receiptMissingReplayFields = receipts.filter((receipt) => !(
+    receipt.source_pdf_path
+    && receipt.source_pdf_sha256
+    && receipt.source_page_render_ref?.sha256
+    && receipt.crop_ref?.sha256
+    && receipt.crop_bbox?.clamped_pixels
