+  };
+}
+
+function buildProductionReadback(manifest, validatorResult) {
+  const postureLines = Object.entries(manifest.summary.qa_posture_counts)
+    .map(([posture, count]) => `- ${posture}: ${count}`);
+  return [
+    '# Wave 1 SourceVisualReceipt Production Readback',
+    '',
+    `Generated: ${manifest.generated_at}`,
+    '',
+    '## Scope',
+    '',
+    '- Issue: #1252, `[FA-CROP-HVY-08] Generate Wave 1 SourceVisualReceipt production rows`',
+    '- Parent issue: #1243',
+    '- Depends on: #1250 / FA-CROP-HVY-06 and #1251 / FA-CROP-HVY-07',
+    '- External VLM calls performed: 0',
+    '- Receipts prove replayable source lineage only; they do not grant rights/display approval.',
+    '',
+    '## Outputs',
+    '',
+    `- Receipt artifact: \`${manifest.output_paths.production_manifest}\``,
+    `- Readback: \`${manifest.output_paths.readback}\``,
+    `- Validator result: \`${manifest.output_paths.validator}\``,
+    '',
+    '## Counts',
+    '',
+    `- Wave 1 rows: ${manifest.summary.wave1_row_count}`,
+    `- Produced crop artifacts considered: ${manifest.summary.produced_crop_artifact_count}`,
+    `- Accepted SourceVisualReceipt rows: ${manifest.summary.accepted_receipt_count}`,
+    `- Replay-validated receipts: ${manifest.summary.replay_validated_receipt_count}`,
