+    '',
+    '## Boundary',
+    '',
+    `- SourceVisualReceipt approvals: ${manifest.summary.source_visual_receipt_approved_true_count}`,
+    `- Rights-display allowed rows: ${manifest.summary.rights_display_allowed_true_count}`,
+    `- SourceFigureAsset student-display acceptance rows: ${manifest.summary.source_figure_accepted_for_student_display_true_count}`,
+    `- Student-display final rows: ${manifest.summary.student_display_eligible_final_true_count}`,
+    '',
+    '## Validation',
+    '',
+    `- Status: ${validatorResult.summary.validation_status}`,
+    `- Checks: ${validatorResult.summary.check_count}`,
+    `- Failed checks: ${validatorResult.summary.failed_check_count}`,
+  ].join('\n');
+}
+
+function buildProductionValidator({ manifest, readback, diagnostics }) {
+  const receipts = asArray(manifest.receipts);
+  const blockers = asArray(manifest.no_receipt_blockers);
+  const qaRows = asArray(manifest.wave1_row_refs);
+  const acceptedCoverageMissing = [];
+  for (const row of qaRows) {
+    const acceptedIds = asArray(row.accepted_crop_artifact_ids);
+    if (row.visual_qa_accepted === true && acceptedIds.length > 0) {
+      for (const cropArtifactId of acceptedIds) {
+        const hasReceipt = receipts.some((receipt) => receipt.crop_ref?.crop_artifact_id === cropArtifactId);
+        const hasBlocker = blockers.some((blockerRow) => asArray(blockerRow.crop_artifact_ids).includes(cropArtifactId));
+        if (!hasReceipt && !hasBlocker) acceptedCoverageMissing.push({ question_key: row.question_key, crop_artifact_id: cropArtifactId });
+      }
+    } else {
+      const hasBlocker = blockers.some((blockerRow) => blockerRow.question_key === row.question_key);
+      if (!hasBlocker) acceptedCoverageMissing.push({ question_key: row.question_key, crop_artifact_id: null });
+    }
+  }
+
+  const receiptMissingReplayFields = receipts.filter((receipt) => !(
+    receipt.source_pdf_path
+    && receipt.source_pdf_sha256
+    && receipt.source_page_render_ref?.sha256
+    && receipt.crop_ref?.sha256
+    && receipt.crop_bbox?.clamped_pixels
+    && receipt.renderer_settings
+    && receipt.qa_posture?.visual_qa_posture
+    && receipt.reviewed_by
+    && receipt.reviewed_at
+  ));
+  const receiptDisplayClaims = receipts.filter((receipt) => (
+    receipt.student_display_eligible_final === true
+    || receipt.rights_display_allowed === true
+    || receipt.source_figure_accepted_for_student_display === true
+  ));
+  const replayFailures = receipts.filter((receipt) => (
+    receipt.review_status !== 'accepted_replayable_lineage'
+    || receipt.deterministic_replay_authority?.crop_hash_match !== true
+    || receipt.deterministic_replay_authority?.replay_status !== 'replay_validated'
+  ));
+  const mixedVlmAuthority = receipts.filter((receipt) => (
+    receipt.deterministic_replay_authority?.model_metadata
+    || receipt.deterministic_replay_authority?.response_ref
+    || receipt.deterministic_replay_authority?.provider
+    || receipt.deterministic_replay_authority?.model_name
+  ));
+  const errorDiagnostics = diagnostics.filter((diagnostic) => diagnostic.severity === 'error');
+  const checks = [
+    check('schema_version', manifest.schema_version === 'source_visual_receipts_production_wave_001.v1', {
+      schema_version: manifest.schema_version,
+    }),
+    check('no_input_diagnostics', errorDiagnostics.length === 0, {
+      error_diagnostic_count: errorDiagnostics.length,
+      sample_diagnostics: errorDiagnostics.slice(0, 10),
+    }),
+    check('wave1_rows_have_receipt_or_explicit_blocker', acceptedCoverageMissing.length === 0, {
+      missing_coverage: acceptedCoverageMissing.slice(0, 25),
+    }),
+    check('accepted_receipts_replay_validated', replayFailures.length === 0, {
+      failed_receipts: replayFailures.map((receipt) => receipt.source_visual_receipt_id).slice(0, 25),
+    }),
+    check('receipts_have_required_replay_fields', receiptMissingReplayFields.length === 0, {
+      missing_field_receipts: receiptMissingReplayFields.map((receipt) => receipt.source_visual_receipt_id).slice(0, 25),
+    }),
+    check('receipts_do_not_grant_student_display_or_rights', receiptDisplayClaims.length === 0, {
+      display_claim_receipts: receiptDisplayClaims.map((receipt) => receipt.source_visual_receipt_id).slice(0, 25),
+    }),
+    check('vlm_metadata_separate_from_deterministic_authority', mixedVlmAuthority.length === 0, {
+      mixed_authority_receipts: mixedVlmAuthority.map((receipt) => receipt.source_visual_receipt_id).slice(0, 25),
+    }),
+    check('no_external_vlm_calls', manifest.boundary.external_vlm_calls_performed === 0, {
+      external_vlm_calls_performed: manifest.boundary.external_vlm_calls_performed,
+    }),
+    check('readback_counts_present', (
+      typeof readback === 'string'
+      && readback.includes('Accepted SourceVisualReceipt rows')
+      && readback.includes('No-receipt blockers')
+    )),
+  ];
+  const failedChecks = checks.filter((item) => item.status !== 'pass');
+  return {
+    schema_version: 'source_visual_receipts_production_wave_001_validator.v1',
+    generated_at: manifest.generated_at,
+    generated_by: 'scripts/method-map/build-source-visual-receipt-replay-harness.mjs',

